/** 查询产品 */
function queryProducts(query = {}) {
    let results = [...PRODUCT_DB];
    if (query.category) {
        results = results.filter(p => p.category === query.category);
    }
    if (query.vendor) {
        const vendorLower = query.vendor.toLowerCase();
        results = results.filter(p => p.vendor.toLowerCase().includes(vendorLower));
    }
    if (query.keyword) {
        const kw = query.keyword.toLowerCase();
        results = results.filter(p => p.name.toLowerCase().includes(kw) ||
            p.description.toLowerCase().includes(kw) ||
            p.keywords.some(k => k.toLowerCase().includes(kw)));
    }
    if (query.pricingTier) {
        results = results.filter(p => p.pricingTier === query.pricingTier);
    }
    if (query.suitableFor) {
        results = results.filter(p => p.suitableFor.includes(query.suitableFor));
    }
    return results;
}
